import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.BAQ5ZYJQ.js";const k=JSON.parse('{"title":"Detached runs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/detached.md","filePath":"guide/detached.md","lastUpdated":1792187838000}'),n={name:"guide/detached.md"};function h(r,e,o,l,d,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="detached-runs" tabindex="-1">Detached runs <a class="header-anchor" href="#detached-runs" aria-label="Permalink to &quot;Detached runs&quot;">​</a></h1><p><code>--batch</code> launches the work and gives you the shell back. It is a <strong>mode, not a layer</strong>: it means the same thing in every context, and what changes is only how each one lets go.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --batch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpu,cluster</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 32,64</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  submitted</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> b7f3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> on</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login.hpc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (batch </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">918273</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), 4 on this machine (l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ocal</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 41288</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> watch</span></span></code></pre></div><table tabindex="0"><thead><tr><th>context</th><th>waiting</th><th>detached</th></tr></thead><tbody><tr><td>local</td><td>subprocess</td><td>a session of its own, which survives the terminal</td></tr><tr><td><code>Ssh</code></td><td>ssh, output streamed</td><td>started over there and released, output to a file</td></tr><tr><td><code>Slurm</code></td><td><code>srun</code></td><td><code>sbatch</code>, which <em>is</em> the detachment: it returns as soon as the job is queued</td></tr></tbody></table><p>Nothing else about the run changes — same paths, same queue, same output.</p><h2 id="the-output-tree-is-the-state" tabindex="-1">The output tree is the state <a class="header-anchor" href="#the-output-tree-is-the-state" aria-label="Permalink to &quot;The output tree is the state&quot;">​</a></h2><p>Because each place writes its <a href="./environments#preparing-then-running">plan</a> before anything runs there, <strong>the arrival of a result file where the plan said one would be is itself the completion signal.</strong> Until a place has written its plan, <code>errand status</code> says it is <em>preparing</em>; where the run is sized from the plan, the preparation is what is submitted, and it submits the run when it knows.</p><p>No protocol between the two sides, no daemon, nothing that can get out of sync. The tree is the <a href="./output">record</a> every run leaves in <code>.errand/runs/</code> — or the visible one, with <code>-o</code> — so a detached run needs no output directory of its own to be followed.</p><p>What is kept locally is only what the tree cannot say — which runs belong to one submission, and what handle each place was given. The side that expanded the matrix is the only one that ever knew those runs went together.</p><h3 id="where-a-run-happened-is-looked-for-when-it-cannot-be-known" tabindex="-1">Where a run happened is looked for when it cannot be known <a class="header-anchor" href="#where-a-run-happened-is-looked-for-when-it-cannot-be-known" aria-label="Permalink to &quot;Where a run happened is looked for when it cannot be known&quot;">​</a></h3><p>A run detached on this machine has a predictable place, and the record says so. A remote one does not — it carries the other machine&#39;s name — and neither does a batch job, which carries the name of whichever compute node the scheduler picked.</p><p>The parameter directory <em>is</em> predictable in every case, so that is what gets searched, and the result naming this run&#39;s environment and parameters is the one.</p><h2 id="keeping-track" tabindex="-1">Keeping track <a class="header-anchor" href="#keeping-track" aria-label="Permalink to &quot;Keeping track&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # one shot, plain text</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> watch</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # the same, live, until everything has landed</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> forget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> b7f3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # drop a submission from the list, keeping its results</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>b7f3  -k bench --fp 32,64 --env gpu,cluster   2026-09-24 12:04   6/8 [######  ]</span></span>
<span class="line"><span>    gpu: local 41288 on this machine - finished</span></span>
<span class="line"><span>    cluster: batch 918273 on login.hpc - running</span></span>
<span class="line"><span>                        gpu@thishost            cluster@node15</span></span>
<span class="line"><span>      cost  fp=32, n=1000   ok seconds=12.4        ok seconds=13.1</span></span>
<span class="line"><span>      cost  fp=32, n=5000   ok seconds=61.2        ok seconds=64.8</span></span>
<span class="line"><span>      cost  fp=64, n=1000   ok seconds=11.2        ...</span></span>
<span class="line"><span>      cost  fp=64, n=5000   ...                    ...</span></span></code></pre></div><p>Grouped by submission, because that is the unit you launched and the unit you will compare.</p><p>Inside one, the matrix reads as a <strong>table</strong> — parameters down, places across — since that is the shape it has, and a flat list of eight lines hides the one axis you were varying. A cell shows the <a href="./declaring-work#the-four-traits">kept</a> number once there is one, so a column slower than its neighbour is visible without opening anything.</p><p><code>errand watch</code> holds no state of its own: it polls the tree and the batch systems, so it can be started, killed and restarted at any point, and several can watch at once.</p><h2 id="the-same-thing-on-a-screen" tabindex="-1">The same thing on a screen <a class="header-anchor" href="#the-same-thing-on-a-screen" aria-label="Permalink to &quot;The same thing on a screen&quot;">​</a></h2><p><a href="./tui"><code>errand tui</code></a> shows this table on its runs page, over the same tree. Tick <code>detach</code> in the launch window, close the window, open it tomorrow: the state was never in the screen.</p><h2 id="results-come-back-when-you-ask" tabindex="-1">Results come back when you ask <a class="header-anchor" href="#results-come-back-when-you-ask" aria-label="Permalink to &quot;Results come back when you ask&quot;">​</a></h2><p>A finished remote run sits there until something collects it. <code>errand status</code> and <code>errand watch</code> are what collect it — results are <a href="./remote#results-are-pulled-not-pushed">pulled, not pushed</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./tui">The screen</a>.</p>`,24)])])}const u=s(n,[["render",h]]);export{k as __pageData,u as default};
